import sys,pathlib,tempfile,subprocess,ctypes as C,struct,json,math
import numpy as np
ROOT=pathlib.Path.cwd();sys.path.insert(0,str(ROOT))
from experiments.sram_size_001.native import Packed48,prepare
out={}
def oracle(u):
 q,r=divmod(u,65536)
 return ((q+int(r>32768 or (r==32768 and q%2)))<<16)&((1<<64)-1)
with tempfile.TemporaryDirectory(prefix='storage-review-') as temp:
 p=pathlib.Path(temp);src=p/'probe.c';src.write_text('#include "'+str(ROOT/'experiments/sram_size_001/history48.h')+'"\nvoid round48(const double*x,double*y,unsigned n){history_store a;for(unsigned i=0;i<n;i++){history_put(&a,0,x[i]);y[i]=history_get(&a,0);}}\nint insert48(void*p,int n,double*x){return history_insert(p,n,x);}\n')
 subprocess.run(['cc','-std=c11','-O2','-shared','-fPIC','-fno-fast-math','-ffp-contract=off',str(src),'-lm','-o',str(p/'probe.so')],check=True)
 lib=C.CDLL(str(p/'probe.so'));lib.round48.argtypes=[C.c_void_p,C.c_void_p,C.c_uint];lib.insert48.argtypes=[C.c_void_p,C.c_int,C.c_void_p]
 rng=np.random.default_rng(781);bits=rng.integers(0,2**64,size=10000,dtype=np.uint64);bits=bits[(bits>>52)&2047 !=2047]
 edge=[]
 for sign in [0,1<<63]:
  for top in [0,1,2,0x000fffffffff,0x001000000000,0x3ff000000000,0x3ff000000001,0x7feffffffffe,0x7fefffffffff]:
   for low in [0,32767,32768,32769,65535]:edge.append(sign|(top<<16)|low)
 bits=np.r_[bits,np.array(edge,dtype=np.uint64)];x=bits.view(np.float64);y=np.empty_like(x);lib.round48(x.ctypes.data,y.ctypes.data,len(x));expected=np.array([oracle(int(u)) for u in bits],dtype=np.uint64)
 assert np.array_equal(y.view(np.uint64),expected)
 out['rounding']={'finite_inputs':len(x),'c_integer_oracle_exact':True,'includes':'positive/negative ties-even, signed zero, subnormal/normal transition and near-overflow'}
 finite=np.isfinite(y);width=1
 class Original:
  width=1
  def dense(self):return np.array([[0.]])
 py=Packed48(Original())
 for a,b in zip(x[finite],y[finite]):
  py.set_dense(np.array([[a]]));assert py.dense()[0,0].view(np.uint64)==b.view(np.uint64)
 out['rounding']['python_c_exact']=True
 for a in [np.finfo(float).max,-np.finfo(float).max]:
  try:py.set_dense(np.array([[a]]));raise AssertionError('accepted overflow')
  except ValueError:pass
 out['overflow']={'python_rejects_positive_negative':True}
 raw=np.zeros(6,dtype=np.uint8);row=np.array([np.finfo(float).max]);out['overflow']['c_return']=lib.insert48(raw.ctypes.data,1,row.ctypes.data);assert out['overflow']['c_return']==-1
 # All-writes QR reference uses libm math.hypot and integer oracle storage.
 def rounded(x):return struct.unpack('<d',struct.pack('<Q',oracle(struct.unpack('<Q',struct.pack('<d',x))[0])))[0]
 n=4;raw=np.zeros(6*n*(n+1)//2,dtype=np.uint8);r=np.zeros((n,n))
 for i in range(1000):
  v=np.array([1.,1.+(i%3)*1e-8,(-1.)**i*1e-6,.5]);work=v.copy();assert lib.insert48(raw.ctypes.data,n,work.ctypes.data)==0
  for j in range(n):
   a,b=r[j,j],v[j];h=math.hypot(a,b)
   if h==0:continue
   c,s=a/h,b/h;r[j,j]=rounded(h)
   for k in range(j+1,n):
    old=r[j,k];vk=v[k];r[j,k]=rounded(c*old+s*vk);v[k]=c*vk-s*old
 packed=Packed48(Original());packed.width=n;packed.values=raw
 # math.hypot can differ from C libc hypot; report finite discrepancy instead of assuming exact.
 err=float(abs(packed.dense()-r).max());out['qr1000']={'max_factor_difference_vs_python_each_write_reference':err}
 # Existing arbitrary artifact is accepted without checking sources, generation or file validity.
 stale=p/'cache'/'tiny_cardinal_1_48';stale.mkdir(parents=True);(stale/'rowwise.so').write_bytes(b'not a library')
 got=prepare(p/'cache','tiny','cardinal',True,48);assert got==stale
 out['cache']={'unverified_existing_binary_accepted':True,'generation_receipt_required':False}
print(json.dumps(out,indent=2));pathlib.Path('/tmp/sram_storage_review_r1_results.json').write_text(json.dumps(out,indent=2))
